import json

# Tragedy of the commons (land/public tragedy) requires all three features:
# 1) a shared resource, 2) individual pursuit of private gain, 3) a collective cost.
options = {
    "A": {"shared_resource": True, "private_gain_pursuit": True, "collective_cost": True},   # arms race dilemma
    "B": {"shared_resource": False, "private_gain_pursuit": False, "collective_cost": False}, # "winners/losers deviate" - no commons structure
    "C": {"shared_resource": True, "private_gain_pursuit": True, "collective_cost": True},   # shared grassland, overgrazing
    "D": {"shared_resource": True, "private_gain_pursuit": True, "collective_cost": True},   # shared water/atmosphere pollution
}

is_tragedy = {k: all(v.values()) for k, v in options.items()}
not_tragedy = sorted(k for k, t in is_tragedy.items() if not t)

final_answer = not_tragedy[0] if len(not_tragedy) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "criteria": ["shared_resource", "private_gain_pursuit", "collective_cost"],
        "is_tragedy": is_tragedy,
        "not_tragedy_options": not_tragedy,
    }
}, separators=(",", ":")))
